-- Central storage14 integration packet. Not executed/registered by the leaf.
-- C adds the provider-native byte/JSON/affinity checks and fixed-layout audit.
CREATE TABLE nx_job_runtime(singleton BIGINT PRIMARY KEY NOT NULL CHECK(singleton=1),deployment TEXT NOT NULL,contract TEXT NOT NULL,epoch TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','paused')));
CREATE TABLE nx_job_queue(singleton BIGINT PRIMARY KEY NOT NULL CHECK(singleton=1),claim_seq BIGINT NOT NULL CHECK(claim_seq>=0));
CREATE TABLE nx_job_grants(deployment TEXT NOT NULL,tenant TEXT NOT NULL,worker TEXT NOT NULL,version BIGINT NOT NULL CHECK(version>0),contract TEXT NOT NULL,epoch TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','revoked')),declaration TEXT NOT NULL,PRIMARY KEY(deployment,tenant,worker));
CREATE TABLE nx_job_tenants(deployment TEXT NOT NULL,tenant TEXT NOT NULL,claim_seq BIGINT NOT NULL CHECK(claim_seq>=0),PRIMARY KEY(deployment,tenant));
CREATE TABLE nx_jobs(id TEXT PRIMARY KEY NOT NULL,deployment TEXT NOT NULL,tenant TEXT NOT NULL,origin TEXT NOT NULL,ordinal BIGINT NOT NULL CHECK(ordinal>=0 AND ordinal<2),worker TEXT NOT NULL,action BIGINT NOT NULL CHECK(action>0),contract TEXT NOT NULL,epoch TEXT NOT NULL,grant_version BIGINT NOT NULL CHECK(grant_version>0),payload TEXT NOT NULL,payload_digest TEXT NOT NULL,due_ms BIGINT NOT NULL CHECK(due_ms>=0),eligible_ms BIGINT NOT NULL CHECK(eligible_ms>=0),first_eligible_ms BIGINT NOT NULL CHECK(first_eligible_ms>=0),attempts BIGINT NOT NULL CHECK(attempts>=0 AND attempts<=5),fence BIGINT NOT NULL CHECK(fence>=0),lease_until_ms BIGINT NOT NULL CHECK(lease_until_ms>=0),state TEXT NOT NULL CHECK(state IN ('pending','running','succeeded','rejected','dead','paused')),reason TEXT NOT NULL,UNIQUE(deployment,origin,ordinal),FOREIGN KEY(deployment,tenant) REFERENCES nx_job_tenants(deployment,tenant));
CREATE INDEX nx_jobs_eligible ON nx_jobs(deployment,state,eligible_ms,id);
CREATE INDEX nx_jobs_quota ON nx_jobs(state,tenant);
CREATE TABLE nx_job_recurring(deployment TEXT NOT NULL,tenant TEXT NOT NULL,name TEXT NOT NULL,contract TEXT NOT NULL,epoch TEXT NOT NULL,grant_version BIGINT NOT NULL CHECK(grant_version>0),version BIGINT NOT NULL CHECK(version>0),state TEXT NOT NULL CHECK(state IN ('active','paused')),next_ms BIGINT NOT NULL CHECK(next_ms>=0),cutoff_ms BIGINT NOT NULL CHECK(cutoff_ms>=0),cutoff_seq BIGINT NOT NULL CHECK(cutoff_seq>=0),cursor TEXT NOT NULL,PRIMARY KEY(deployment,tenant,name));
CREATE TABLE nx_job_occurrences(deployment TEXT NOT NULL,tenant TEXT NOT NULL,schedule TEXT NOT NULL,occurrence TEXT NOT NULL,job TEXT NOT NULL,PRIMARY KEY(deployment,tenant,schedule,occurrence),FOREIGN KEY(job) REFERENCES nx_jobs(id));
